HERE=ROOT/'campaigns/nas-source-period-audit-20261008-v1'
NAME='source-period-audit-v1'
sources=json.loads("{\"observer.c\":\"/* 対応一次実装を純粋観測し、周期・位相・実パルス発生を記録する。 */\\n#include \\\"HTS_hidden.h\\\"\\n#include <math.h>\\n#include <stddef.h>\\n#include <stdint.h>\\n#include <string.h>\\nstatic double *tr_period=NULL,*tr_counter=NULL;\\nstatic uint8_t *tr_pulse=NULL;\\nstatic size_t tr_index=0,tr_capacity=0;\\nstatic double tr_observe(HTS_Vocoder *v,const double *lpf);\\n#define HTS_Vocoder_initialize TRACE_Vocoder_initialize\\n#define HTS_Vocoder_synthesize TRACE_Vocoder_synthesize\\n#define HTS_Vocoder_clear TRACE_Vocoder_clear\\n#include \\\"HTS_vocoder_observed.c\\\"\\n#undef HTS_Vocoder_initialize\\n#undef HTS_Vocoder_synthesize\\n#undef HTS_Vocoder_clear\\nstatic double tr_observe(HTS_Vocoder *v,const double *lpf) {\\n    double p=v->pitch_of_curr_point,c=v->pitch_counter;\\n    uint8_t pulse=p>0. && c+1.>=p;\\n    /* 元の励振処理は1回だけ呼ぶ。乱数・状態・filter・係数を変更しない。 */\\n    double x=HTS_Vocoder_get_excitation(v,lpf);\\n    if (tr_index<tr_capacity) {\\n        tr_period[tr_index]=p;tr_counter[tr_index]=c;tr_pulse[tr_index]=pulse;\\n    }\\n    tr_index++;return x;\\n}\\nint trace_render(const double *mcp,const double *lf0,const double *lpf,\\n    const double *native_initial_mcp,int use_native_initial,size_t frames,size_t cols,size_t nlpf,\\n    double *out,double *period,double *counter,uint8_t *pulse,size_t samples) {\\n    if (tr_capacity || !mcp || !lf0 || !lpf || !native_initial_mcp || !out ||\\n        !period || !counter || !pulse || frames<1 || frames>6000 || cols!=35 ||\\n        nlpf<1 || nlpf>63 || nlpf%2!=1 || samples!=frames*240 ||\\n        (use_native_initial!=0 && use_native_initial!=1)) return 0;\\n    for (size_t f=0;f<frames;f++) {\\n        if (!isfinite(lf0[f]) || (lf0[f]!=LZERO && (exp(lf0[f])<70. || exp(lf0[f])>800.))) return 0;\\n        for (size_t j=0;j<35;j++) if (!isfinite(mcp[f*35+j])) return 0;\\n        for (size_t j=0;j<nlpf;j++) if (!isfinite(lpf[f*nlpf+j])) return 0;\\n    }\\n    for (size_t j=0;j<35;j++) if (!isfinite(native_initial_mcp[j])) return 0;\\n    HTS_Vocoder v;TRACE_Vocoder_initialize(&v,34,0,FALSE,48000,240);\\n    if (use_native_initial) {\\n        double p=lf0[0]==LZERO ? 0. : v.rate/exp(lf0[0]);\\n        HTS_Vocoder_initialize_excitation(&v,p,nlpf);\\n        HTS_mc2b(native_initial_mcp,v.c,34,.55);\\n        v.is_first=FALSE;\\n    }\\n    tr_period=period;tr_counter=counter;tr_pulse=pulse;tr_capacity=samples;tr_index=0;\\n    for (size_t f=0;f<frames;f++) {\\n        double mc[35],lp[63];memcpy(mc,mcp+f*35,35*sizeof(double));\\n        memcpy(lp,lpf+f*nlpf,nlpf*sizeof(double));\\n        TRACE_Vocoder_synthesize(&v,34,lf0[f],mc,nlpf,lp,.55,0.,1.,out+f*240,NULL);\\n    }\\n    size_t actual=tr_index;\\n    tr_period=NULL;tr_counter=NULL;tr_pulse=NULL;tr_index=0;tr_capacity=0;\\n    TRACE_Vocoder_clear(&v);\\n    if (actual!=samples) return 0;\\n    for (size_t i=0;i<samples;i++) if (!isfinite(out[i]) || !isfinite(period[i]) ||\\n        !isfinite(counter[i]) || period[i]<0.) return 0;\\n    return 1;\\n}\",\"observer.py\":\"\\\"\\\"\\\"既存HTS入力の純粋周期観測。保存波形を生成材料へ戻さない。\\\"\\\"\\\"\\nimport ctypes as C,hashlib,io\\nfrom pathlib import Path\\nimport numpy as np\\nfrom scipy import signal\\nfrom scipy.io import wavfile\\nfrom hts_arrays import validated,ah\\nP=C.POINTER(C.c_double);U=C.POINTER(C.c_uint8);S=C.c_size_t\\n_lib=C.CDLL(str(Path(__file__).resolve().parent/'observer.dylib'))\\n_fn=_lib.trace_render;_fn.restype=C.c_int\\n_fn.argtypes=[P,P,P,P,C.c_int,S,S,S,P,P,P,U,S]\\ndef observe(params,settings,native_initial,use_native_initial):\\n    x=validated(params,settings);before=[ah(a) for a in x]\\n    first=np.ascontiguousarray(native_initial,dtype=np.float64)\\n    assert first.shape==(35,) and np.isfinite(first).all()\\n    first_hash=ah(first)\\n    n=len(x[0])*240\\n    raw=np.empty(n);period=np.empty(n);counter=np.empty(n);pulse=np.empty(n,dtype=np.uint8)\\n    if not _fn(*(a.ctypes.data_as(P) for a in x),first.ctypes.data_as(P),int(use_native_initial),\\n        len(x[0]),35,x[2].shape[1],raw.ctypes.data_as(P),period.ctypes.data_as(P),\\n        counter.ctypes.data_as(P),pulse.ctypes.data_as(U),n):\\n        raise RuntimeError('純粋周期観測の内部検査に不通過')\\n    assert [ah(a) for a in x]==before and ah(first)==first_hash\\n    expected=(period>0)&(counter+1>=period)\\n    assert np.array_equal(pulse.astype(bool),expected)\\n    idx=np.arange(n-1);same_frame=idx%240!=239;voiced=period[:-1]>0\\n    predicted=counter[:-1]+1-pulse[:-1]*period[:-1]\\n    assert np.array_equal(counter[1:][same_frame&voiced],predicted[same_frame&voiced])\\n    assert np.array_equal(counter[1:][same_frame&~voiced],counter[:-1][same_frame&~voiced])\\n    boundary=np.arange(239,n-1,240)\\n    continuous=(x[1][:-1,0]>0)&(x[1][1:,0]>0)\\n    assert counter[0]==period[0]\\n    assert np.array_equal(counter[boundary+1][continuous],predicted[boundary][continuous])\\n    assert np.array_equal(counter[boundary+1][~continuous],period[boundary+1][~continuous])\\n    audio=signal.resample_poly(raw/32768.,1,2)\\n    fade=min(round(.012*24000),len(audio)//2);envelope=np.sin(np.linspace(0,np.pi/2,fade))**2\\n    audio[:fade]*=envelope;audio[-fade:]*=envelope[::-1]\\n    out=io.BytesIO();wavfile.write(out,24000,(audio*.25).astype(np.float32));data=out.getvalue()\\n    return data,dict(period=period,counter_before=counter,pulse=pulse),dict(\\n        sha256=hashlib.sha256(data).hexdigest(),actual_render=1,\\n        sample_clock=48000,sample_count=n,pulse_count=int(pulse.sum()),\\n        no_state_writes_by_observer=True,one_original_excitation_call_per_sample=True,\\n        phase_recurrence_exact=True,input_streams_unchanged=True,source_period_only=True,\\n        perceived_pitch_truth_claimed=False)\\ndef ground(period,times):\\n    rows=[];freq=np.zeros(len(period));mask=period>0;freq[mask]=48000/period[mask]\\n    for t in times:\\n        c=round(float(t)*48000);a,b=c-1440,c+1440\\n        typ='edge';hz=None\\n        if a>=0 and b<=len(period) and (period[a:b]>0).all():\\n            f=freq[a:b];spread=float(12*np.log2(f.max()/f.min()))\\n            if spread<=1.:typ='positive';hz=float(np.median(f))\\n            else:typ='dynamic'\\n        elif c>=960 and c+960<=len(period) and (period[c-960:c+960]==0).all():\\n            typ='negative'\\n        elif a>=0 and b<=len(period):typ='boundary'\\n        rows.append(dict(time=float(t),kind=typ,source_hz=hz))\\n    return rows\\ndef score(values,times,period):\\n    gt=ground(period,times);positive=np.array([r['kind']=='positive' for r in gt])\\n    negative=np.array([r['kind']=='negative' for r in gt]);accepted=(values>=70)&(values<=800)\\n    target=np.array([r['source_hz'] or 1. for r in gt]);errors=np.full(len(values),np.inf)\\n    errors[accepted]=np.abs(12*np.log2(values[accepted]/target[accepted]))\\n    correct=positive&accepted&(errors<=1.);p=int(positive.sum());n=int(negative.sum())\\n    coverage=float(correct.sum()/p) if p else 0.;false=int((negative&accepted).sum())\\n    uv=float(false/n) if n else 1.\\n    med=float(np.median(errors[positive])) if p else None\\n    return dict(positive_frames=p,negative_frames=n,correct_positive=int(correct.sum()),\\n        accepted_positive=int((positive&accepted).sum()),positive_missing=int((positive&~accepted).sum()),\\n        coverage=coverage,median_error_semitones=med if med is not None and np.isfinite(med) else None,\\n        negative_false_accept=false,negative_false_accept_rate=uv,\\n        exclusions={k:sum(r['kind']==k for r in gt) for k in ['edge','dynamic','boundary']},\\n        passed=bool(p>=3 and n>=3 and coverage>=.9 and med is not None and med<=1. and uv<=.05),\\n        excitation_period_diagnostic_only=True,perceived_pitch_truth=False)\\n\",\"prepare.py\":\"\\\"\\\"\\\"旧封印・対応一次実装・全依存を固定し、観測入口だけを構築する。\\\"\\\"\\\"\\nfrom paths import *\\nimport ast,subprocess\\ndef main():\\n    b=Budget();b.recover()\\n    with b.job(NAME,'setup','一次HTSの純粋観測変更と既存依存の同梱',reserve_bytes=20_000_000) as j:\\n        original=(SOURCE/'upstream/HTS_vocoder.c').read_text()\\n        assert digest(SOURCE/'upstream/HTS_vocoder.c')=='f5b97b331639af246dea3871a74bca512f40d96618702f6512d8e0fbed86cdd9'\\n        needle='x = HTS_Vocoder_get_excitation(v, lpf);';assert original.count(needle)==1\\n        observed=original.replace(needle,'x = tr_observe(v, lpf);')\\n        b.write(HERE/'HTS_vocoder_observed.c',observed.encode(),j)\\n        b.save(HERE/'source-change-audit.json',dict(primary_sha256=digest(SOURCE/'upstream/HTS_vocoder.c'),\\n            source_commit='214e26dfb7f728ff9db39c14a59db709abcc121d',\\n            replaced_call_site_count=1,old_call=needle,new_call='x = tr_observe(v, lpf);',\\n            all_other_primary_source_bytes_unchanged=True,observer_no_vocoder_state_writes=True,\\n            no_new_synthesis_rule=True,excitation_truth_only=True,perceived_pitch_truth=False),j)\\n        names=['local_renderer.py','local_hts-v2.dylib','hts_arrays.py','hts_arrays.dylib','acoustics.py',\\n               'postfilter_v2.py','postfilter_v2.dylib','HTS-BSD-NOTICE.txt','LICENSE-WORLD.txt']\\n        previous=read(PREVIOUS/'artifact-seal.json')['files'];bundle=HERE/'runtime-bundle'\\n        for n in names:\\n            p=PREVIOUS/'runtime-bundle'/n;assert digest(p)==previous[str(p.relative_to(REPO))]\\n            b.write(bundle/n,p.read_bytes(),j)\\n        package=LATEST/'runtime-bundle/packages-v2'\\n        latest=read(LATEST/'artifact-seal.json')['files']\\n        for p in package.rglob('*'):\\n            if p.is_file():\\n                assert digest(p)==latest[str(p.relative_to(REPO))]\\n                b.write(bundle/'packages-v2'/p.relative_to(package),p.read_bytes(),j)\\n        b.write(bundle/'period_measurement.py',(HERE/'period_measurement.py').read_bytes(),j)\\n        b.write(bundle/'observer.py',(HERE/'observer.py').read_bytes(),j)\\n        # pyworldのパスを、ライブラリimport前に子が指定する。\\n    tool=Path('/Applications/Xcode.app/Contents/Developer/Toolchains/XcodeDefault.xctoolchain/usr/bin/clang')\\n    sdk=Path('/Applications/Xcode.app/Contents/Developer/Platforms/MacOSX.platform/Developer/SDKs/MacOSX.sdk')\\n    assert tool.is_file() and sdk.is_dir()\\n    cmd=[str(tool),'-dynamiclib','-O2','-fno-modules','-undefined','dynamic_lookup','-isysroot',str(sdk),\\n        '-I'+str(HERE/'vendor'),'-I'+str(HERE),str(HERE/'observer.c'),'-o',str(HERE/'runtime-bundle/observer.dylib')]\\n    with b.job(NAME,'setup','観測Cのbuildと専用一時物の削除',reserve_bytes=20_000_000) as j:\\n        with b.workspace(j,'clang中間物とcache',16_000_000,32_000_000) as (work,env):\\n            env['CLANG_MODULE_CACHE_PATH']=str(work/'clang-modules')\\n            with b.external_output(HERE/'runtime-bundle/observer.dylib',100_000,j):\\n                result=subprocess.run(cmd,env=env,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,check=True,timeout=120)\\n        b.save(HERE/'build-audit.json',dict(command=cmd,stderr=result.stderr,returncode=result.returncode,\\n            source_sha256=digest(HERE/'observer.c'),binary_sha256=digest(HERE/'runtime-bundle/observer.dylib'),\\n            all_temporary_removed=True,new_download=0),j)\\n    with b.job(NAME,'setup','観測前の全ソース・旧128入力契約を固定',reserve_bytes=400_000) as j:\\n        p=read(PREVIOUS/'protocol.json');records=[]\\n        for row in p['rows']:\\n            for condition in p['conditions']:\\n                for method in ['hts_native','hts_postfilter','hts_voicing','hts_voicing_postfilter']:\\n                    base=PREVIOUS/'render'/row['id']/condition/method;x=read(base.with_suffix('.json'))\\n                    assert x['status']=='completed' and digest(REPO/x['wav'])==x['wav_sha256']\\n                    assert digest(base.with_suffix('.json'))==read(PREVIOUS/'artifact-seal.json')['files'][str(base.with_suffix('.json').relative_to(REPO))]\\n                    records.append(dict(id=row['id']+'/'+condition+'/'+method,row=row,condition=condition,method=method,\\n                        old_record=str(base.with_suffix('.json').relative_to(REPO)),old_record_sha256=digest(base.with_suffix('.json')),\\n                        parameters=str(base.with_suffix('.npz').relative_to(REPO)),parameters_sha256=digest(base.with_suffix('.npz')),\\n                        native_initial=str(base.with_name('native').with_suffix('.npz').relative_to(REPO)),\\n                        native_initial_sha256=digest(base.with_name('native').with_suffix('.npz'))))\\n        assert len(records)==128\\n        b.save(HERE/'protocol.json',dict(records=records,conditions=p['conditions'],registration_sha256=digest(HERE/'registration.json'),\\n            inputs_are_existing_audit_only=True,no_prospective_quality_claim=True,protected_confirmation_opened=False),j)\\n        bundle=HERE/'runtime-bundle'\\n        b.save(bundle/'manifest.json',dict(files={str(p.relative_to(bundle)):digest(p) for p in bundle.rglob('*') if p.is_file()},\\n            observer_only=True,diagnostic_from_saved_parameters=True,final_generator_qualification=False),j)\\n        for p in HERE.glob('*.py'):ast.parse(p.read_text(),filename=str(p))\\n        b.save(HERE/'execution-contract.json',dict(registration_sha256=digest(HERE/'registration.json'),\\n            protocol_sha256=digest(HERE/'protocol.json'),source_hashes={p.name:digest(p) for p in HERE.glob('*.py')},\\n            C_source_sha256=digest(HERE/'observer.c'),observed_primary_sha256=digest(HERE/'HTS_vocoder_observed.c'),\\n            runtime_manifest_sha256=digest(bundle/'manifest.json'),all_conditions_fixed_before_output=True,\\n            observer_only=True,old_gates_unchanged=True,quality_goal_completed=False),j)\\n    print(b.reconcile(),flush=True)\\nif __name__=='__main__':main()\\n\",\"controller.py\":\"\\\"\\\"\\\"128既存HTS波形の純粋観測監査。旧波形との一致が必須。\\\"\\\"\\\"\\nfrom paths import *\\nimport argparse,base64,io,json,os,subprocess,sys\\nfrom contextlib import ExitStack\\ndef verify():\\n    c=read(HERE/'execution-contract.json')\\n    assert digest(HERE/'registration.json')==c['registration_sha256']\\n    assert digest(HERE/'protocol.json')==c['protocol_sha256']\\n    assert digest(HERE/'observer.c')==c['C_source_sha256']\\n    assert digest(HERE/'HTS_vocoder_observed.c')==c['observed_primary_sha256']\\n    for n,h in c['source_hashes'].items():assert digest(HERE/n)==h,n\\n    assert digest(HERE/'runtime-bundle/manifest.json')==c['runtime_manifest_sha256']\\n    for n,h in read(HERE/'runtime-bundle/manifest.json')['files'].items():assert digest(HERE/'runtime-bundle'/n)==h,n\\ndef imports():\\n    import tempfile\\n    assert Path(tempfile.gettempdir()).resolve()==Path(os.environ['TMPDIR']).resolve()\\n    sys.path[:0]=[str(HERE/'runtime-bundle'),str(HERE/'runtime-bundle/packages-v2')]\\n    import numpy as np\\n    from scipy.io import wavfile\\n    import observer,period_measurement,hts_arrays,postfilter_v2\\n    assert callable(period_measurement.trackers)\\n    return np,wavfile,observer,period_measurement,hts_arrays,postfilter_v2\\ndef preflight_worker():\\n    np,wavfile,obs,measure,hts,pf=imports()\\n    settings=dict(stage=0.,use_log_gain=0.,sampling_frequency=48000.,fperiod=240.,alpha=.55,beta=0.,volume=1.,audio_buff_size=0.,stop=0.)\\n    results=[]\\n    for pitch in [110.,220.]:\\n        mcp=np.zeros((100,35));mcp[:,0]=7.\\n        lf0=np.full((100,1),-1e10);lf0[20:80]=np.log(pitch)\\n        lpf=np.ones((100,1));params=[mcp,lf0,lpf]\\n        baseline,_=hts.synthesize(params,settings)\\n        data,trace,meta=obs.observe(params,settings,mcp[0],False)\\n        out=io.BytesIO();wavfile.write(out,24000,(baseline*.25).astype(np.float32))\\n        assert data==out.getvalue()\\n        assert np.allclose(trace['period'][20*240:80*240],48000/pitch,rtol=0,atol=1e-12)\\n        assert not np.any(trace['period'][:20*240]) and not np.any(trace['period'][80*240:])\\n        from acoustics import evaluate\\n        assert evaluate(baseline*.25,{},24000)['E0_pass']\\n        for name,wave in [('reference',out.getvalue()),('observed',data)]:\\n            results.append(dict(name=str(int(pitch))+'-'+name,sha256=__import__('hashlib').sha256(wave).hexdigest(),wav_base64=base64.b64encode(wave).decode()))\\n    return dict(results=results,actual_render=4,E0_calls=2,constant_period_and_unvoiced_truth_pass=True,\\n        phase_recurrence_exact=True,byte_exact=True,fixture_not_quality_evidence=True)\\ndef worker(render_job,dsp_job):\\n    np,wavfile,obs,measure,hts,pf=imports()\\n    from acoustics import evaluate\\n    b=Budget();p=read(HERE/'protocol.json');rows=[];new=0;reused=0\\n    for item in p['records']:\\n        target=HERE/'diagnostic'/(item['id']+'.json')\\n        if target.exists():\\n            saved=read(target);assert saved['old_record_sha256']==item['old_record_sha256'] and saved['byte_exact']\\n            assert digest(REPO/saved['trace_path'])==saved['trace_sha256']\\n            rows.append(dict(id=item['id'],path=str(target.relative_to(REPO)),sha256=digest(target)));reused+=1;continue\\n        for key,hkey in [('old_record','old_record_sha256'),('parameters','parameters_sha256'),('native_initial','native_initial_sha256')]:\\n            assert digest(REPO/item[key])==item[hkey],item['id']\\n        old=read(REPO/item['old_record']);assert digest(REPO/old['wav'])==old['wav_sha256']\\n        with np.load(REPO/item['parameters']) as a:params=[a[n].copy() for n in ['mcp','lf0','lpf']]\\n        with np.load(REPO/item['native_initial']) as a:first=a['mcp'][0].copy()\\n        use='postfilter' in item['method']\\n        data,trace,meta=obs.observe(params,old['meta']['settings'],first,use);new+=1\\n        assert meta['sha256']==old['wav_sha256'],'観測で旧波形が変化したため停止'\\n        _,audio=wavfile.read(io.BytesIO(data));e0=evaluate(audio,{},24000);assert e0['E0_pass']==old['E0_pass']\\n        trackers,legacy,confidence=measure.trackers(audio)\\n        scores={name:obs.score(values,times,trace['period']) for name,(values,times) in trackers.items()}\\n        support=old['measurement']['support'];bounds=np.r_[0,np.cumsum(old['meta']['duration'])]*240\\n        source_support=[]\\n        for i in support:\\n            a,z=int(bounds[i*5]),int(bounds[(i+1)*5]);chunk=trace['period'][a:z];v=chunk[chunk>0]\\n            source_support.append(dict(index=i,source_voiced_samples=int(len(v)),source_samples=len(chunk),\\n                source_median_hz=float(np.median(48000/v)) if len(v) else None,\\n                duration_ms=(z-a)/48,primary_center_window_60ms_exclusion_possible=(z-a)<2880))\\n        buffer=io.BytesIO();arrays=dict(trace,acf_confidence=confidence)\\n        for name,(values,times) in trackers.items():arrays[name]=values;arrays[name+'_times']=times\\n        np.savez_compressed(buffer,**arrays);tracepath=HERE/'trace'/(item['id']+'.npz')\\n        if tracepath.exists():\\n            with np.load(tracepath) as old_arrays,np.load(io.BytesIO(buffer.getvalue())) as new_arrays:\\n                assert set(old_arrays.files)==set(new_arrays.files) and all(np.array_equal(old_arrays[k],new_arrays[k]) for k in old_arrays.files)\\n        else:b.write(tracepath,buffer.getvalue(),dsp_job)\\n        value=dict(id=item['id'],condition=item['condition'],method=item['method'],length=item['row']['length'],\\n            old_record=item['old_record'],old_record_sha256=item['old_record_sha256'],old_wav=old['wav'],\\n            old_wav_sha256=old['wav_sha256'],observed_wav_sha256=meta['sha256'],byte_exact=True,\\n            parameter_sha256=item['parameters_sha256'],native_initial_sha256=item['native_initial_sha256'],\\n            use_native_initial=use,E0=e0,observer_meta=meta,trackers=scores,legacy_ACF_diagnostic=legacy,\\n            old_pitch_gate_unchanged=old['pitch_gate'],old_fixed_support_source=source_support,\\n            source_GT_clock_diagnostic_only=True,source_period_is_not_perceived_pitch_truth=True,\\n            old_qualification_changed=False,trace_path=str(tracepath.relative_to(REPO)),trace_sha256=digest(tracepath))\\n        b.write_data(target,encode(value),dsp_job)\\n        rows.append(dict(id=item['id'],path=str(target.relative_to(REPO)),sha256=digest(target)))\\n        print('観測',len(rows),'/128',flush=True)\\n    assert len(rows)==128\\n    b.save(HERE/'diagnostic-manifest.json',dict(rows=rows,new_render=new,reused=reused,new_DSP=new*6,\\n        all_byte_exact=True,quality_goal_completed=False),dsp_job)\\ndef main():\\n    p=argparse.ArgumentParser();p.add_argument('stage',choices=['preflight','preflight-worker','observe','observe-worker'])\\n    p.add_argument('--render-job');p.add_argument('--dsp-job');a=p.parse_args();verify()\\n    if a.stage=='preflight-worker':print(json.dumps(preflight_worker(),allow_nan=False));return\\n    if a.stage=='observe-worker':worker(a.render_job,a.dsp_job);return\\n    b=Budget();b.recover()\\n    if a.stage=='preflight':\\n        assert not (HERE/'preflight-audit.json').exists()\\n        with ExitStack() as stack:\\n            j=stack.enter_context(b.job(NAME,'render','定周期2条件の観測/reference4fixture',count=4,reserve_bytes=12_000_000))\\n            stack.enter_context(b.job(NAME,'dsp','4fixtureのE0・hash・内部周期',count=4,reserve_bytes=100_000))\\n            with b.workspace(j,'fixtureライブラリ初期化') as (_,env):\\n                result=subprocess.run([str(PYTHON),'-B',str(HERE/'controller.py'),'preflight-worker'],env=env,stdout=subprocess.PIPE,text=True,check=True,timeout=300)\\n            x=json.loads(result.stdout)\\n            for row in x['results']:\\n                data=base64.b64decode(row.pop('wav_base64'),validate=True)\\n                assert __import__('hashlib').sha256(data).hexdigest()==row['sha256']\\n                b.write(HERE/'fixtures'/(row['name']+'.wav'),data,j)\\n            b.save(HERE/'preflight-audit.json',x,j)\\n    else:\\n        assert read(HERE/'preflight-audit.json')['byte_exact']\\n        count=sum(not (HERE/'diagnostic'/(x['id']+'.json')).exists() for x in read(HERE/'protocol.json')['records'])\\n        assert count>0,'保存済み観測は再実行しない'\\n        with b.job(NAME,'render','128既存HTS入力の純粋観測',count=count,reserve_bytes=12_000_000) as r:\\n            with b.job(NAME,'dsp','既存周期と3測定/legacy/E0/参照整合',count=count*6,reserve_bytes=300_000_000) as d:\\n                with b.workspace(r,'純粋観測・測定ライブラリ初期化') as (_,env):\\n                    subprocess.run([str(PYTHON),'-B',str(HERE/'controller.py'),'observe-worker','--render-job',r,'--dsp-job',d],\\n                        env=env,check=True,timeout=10800)\\n    print(b.reconcile(),flush=True)\\nif __name__=='__main__':main()\\n\",\"summarize.py\":\"\\\"\\\"\\\"旧128音声の分母・除外・欠測・限定測定資格を保持する。\\\"\\\"\\\"\\nfrom paths import *\\nfrom controller import verify\\ndef main():\\n    verify();b=Budget();b.recover();p=read(HERE/'protocol.json');manifest=read(HERE/'diagnostic-manifest.json')\\n    assert len(manifest['rows'])==128 and manifest['all_byte_exact']\\n    with b.job(NAME,'audit','全観測hash・適用分母・測定不通過を集計',reserve_bytes=2_000_000) as j:\\n        records=[]\\n        for x in manifest['rows']:\\n            assert digest(REPO/x['path'])==x['sha256']\\n            v=read(REPO/x['path']);assert digest(REPO/v['old_wav'])==v['old_wav_sha256']==v['observed_wav_sha256']\\n            assert digest(REPO/v['trace_path'])==v['trace_sha256'];records.append(v)\\n        results={}\\n        for tracker in ['dio','harvest','centered_acf']:\\n            groups={}\\n            for condition in ['both','neutral','higher']:\\n                for method in ['all','hts_native','hts_postfilter','hts_voicing','hts_voicing_postfilter']:\\n                    chosen=[r for r in records if (condition=='both' or r['condition']==condition) and (method=='all' or r['method']==method)]\\n                    s=[r['trackers'][tracker] for r in chosen];assert chosen\\n                    groups[condition+'/'+method]=dict(expected=len(chosen),passed=sum(x['passed'] for x in s),\\n                        positive_frames=sum(x['positive_frames'] for x in s),negative_frames=sum(x['negative_frames'] for x in s),\\n                        correct_positive=sum(x['correct_positive'] for x in s),positive_missing=sum(x['positive_missing'] for x in s),\\n                        negative_false_accept=sum(x['negative_false_accept'] for x in s),\\n                        exclusions={k:sum(x['exclusions'][k] for x in s) for k in ['edge','dynamic','boundary']},\\n                        inadequate_positive=sum(x['positive_frames']<3 for x in s),inadequate_negative=sum(x['negative_frames']<3 for x in s),\\n                        all_pass=all(x['passed'] for x in s))\\n            results[tracker]=dict(groups=groups,all_128_pass=groups['both/all']['all_pass'],\\n                failed_ids=[r['id'] for r in records if not r['trackers'][tracker]['passed']],\\n                scope='第19回HTS128音声の60ms安定全有声窓/20ms全無声窓と実励振周期だけ。知覚ピッチ・WORLD・日本語一般・旧ゲートには拡張しない。',\\n                independent_vote=False)\\n        b.save(HERE/'aggregate-summary.json',dict(total=128,all_byte_exact=True,results=results,\\n            old_gates_and_decisions_unchanged=True,legacy_ACF_is_diagnostic_only=True,\\n            trace_is_source_excitation_not_perceived_pitch=True,new_content_evaluation=0,\\n            final_generator_independence_not_retested=True,perceptual_qualification=False,\\n            protected_confirmation_opened=False,quality_goal_completed=False),j)\\n    print({n:x['all_128_pass'] for n,x in results.items()},flush=True);print(b.reconcile(),flush=True)\\nif __name__=='__main__':main()\\n\",\"closeout.py\":\"\\\"\\\"\\\"純粋観測監査を封印し、旧科学判定を保持する。\\\"\\\"\\\"\\nfrom paths import *\\nfrom controller import verify\\ndef main():\\n    verify();b=Budget();b.recover();assert not b.snapshot()['jobs']\\n    s=read(HERE/'aggregate-summary.json')\\n    assert s['total']==128 and s['all_byte_exact'] and not s['quality_goal_completed']\\n    with b.job(NAME,'audit','純粋観測監査の外部hash・費用・不採択を封印',reserve_bytes=4_000_000) as j:\\n        n=b.audit_data_hashes();v=b.snapshot();c=v['campaigns'][NAME]\\n        assert all(w['status']=='removed' and w['absence_verified'] for w in v['temporary_work'].values())\\n        assert all(c['counts'].get(k,0)<=lim for k,lim in c['limits'].items() if k not in ['seconds','bytes'])\\n        assert v['seconds']-c['start_seconds']<c['limits']['seconds'] and c['payload_bytes']<c['limits']['bytes']\\n        b.save(HERE/'cost-audit.json',dict(actual_render=132,actual_comparison=128,actual_fixture=4,\\n            conservative_render=c['counts']['render'],conservative_DSP=c['counts']['dsp'],AI=0,\\n            technical_retries=0,unused_reservations_not_returned=True,campaign=c,whole_cycle_counts=v['counts'],\\n            all_temporary_removed=True,new_teacher_train_inverse_download_money=0),j)\\n        lines=['# 既存HTS励振周期の純粋観測監査','','第19回の既存16文×2条件×HTS4方式、全128波形が旧波形hashと一致。新しい生成規則は追加していない。','',\\n            '|測定|限定窓の全128通過|通過件数|','|---|---|---:|']\\n        for name,x in s['results'].items():lines.append(f\\\"|{name}|{x['all_128_pass']}|{x['groups']['both/all']['passed']}/128|\\\")\\n        lines+=['','60msの安定全有声窓と20msの全無声窓が対象。境界・変動・短い区間は理由と分母を保存。欠測・不足を不通過に含む。',\\n            '実励振の周期・位相・パルスを記録した。知覚ピッチの真値、WORLD、日本語一般の資格には広げない。旧ゲートと採否は変更していない。',\\n            '4定周期fixtureと128観測で実生成132回。ASR・教師・学習・逆推定・音声/模型取得・新しい人の回答は0。全一時領域は削除確認済み。',\\n            '保護P5未開封、知覚資格不足、全体品質未達。次は既存結果の因果別整理・サイクル終了監査へ進む。','']\\n        b.write(HERE/'report.md','\\\\n'.join(lines).encode(),j)\\n        files={str(p.relative_to(REPO)):digest(p) for p in HERE.rglob('*') if p.is_file()}\\n        b.save(HERE/'artifact-seal.json',dict(files=files,path_base='repository',external_hash_verified=n,\\n            experiment_completed=True,observer_only=True,quality_certified=False,quality_goal_completed=False),j)\\n        b.save(HERE/'completion-audit.json',dict(files_verified=len(files),seal_sha256=digest(HERE/'artifact-seal.json'),\\n            all_temporary_removed=True,old_qualification_unchanged=True,quality_goal_completed=False),j)\\n    b.close_campaign(NAME)\\n    b.save(ROOT/'progress-0028.json',dict(latest_completed=str(HERE.relative_to(ROOT)),active_campaign=None,\\n        observation_records=128,actual_render=132,actual_AI=0,all_byte_exact=True,quality_goal_completed=False,\\n        protected_confirmation_opened=False,next='既存比較の因果別整理とサイクル終了監査。',git_save_pending=True,budget=b.reconcile()))\\n    print(b.reconcile(),flush=True)\\nif __name__=='__main__':main()\\n\"}")
def construct():
    paths=(LATEST/'paths.py').read_text().replace("NAME = 'gv-ap-interaction-v1'","NAME = 'source-period-audit-v1'")
    paths=paths.replace("PREVIOUS = ROOT / 'campaigns/nas-gv-ablation-20261008-v1'","PREVIOUS = ROOT / 'campaigns/nas-mcp-postfilter-20261008-v1'")
    paths+="\nLATEST = ROOT / 'campaigns/nas-gv-ap-interaction-20261008-v1'\n"
    sources['paths.py']=paths
    sources['temporary_storage.py']=(LATEST/'temporary_storage.py').read_text().replace("owner = 'gv-ap-interaction-'","owner = 'source-period-audit-'")
    sources['period_measurement.py']=(LATEST/'period_measurement.py').read_text()
    for n,s in sources.items():
        if n.endswith('.py'):ast.parse(s,filename=n)
    assert "PREVIOUS = ROOT / 'campaigns/nas-mcp-postfilter-20261008-v1'" in paths
    assert set(sources)==set(['observer.c','observer.py','prepare.py','controller.py','summarize.py','closeout.py','paths.py','temporary_storage.py','period_measurement.py'])
def main():
    construct();b=Budget();b.recover();v=b.snapshot()
    assert not v['jobs'] and len(v['campaigns'])==21 and all(c['closed'] for c in v['campaigns'].values())
    draft=read(ROOT/'next-source-period-audit-draft-0001.json')
    summary=read(LATEST/'aggregate-summary.json')
    reg=dict(question='既存HTS音声の実励振周期を純粋観測したとき、DIO/Harvest/中心ACFは、事前限定の安定有声/無声窓で欠測と誤りをどの程度生じるか。',
        existing_route_audit_only=True,previous_GV_AP_qualifications=summary['qualifications'],
        latest_seal_sha256=digest(LATEST/'artifact-seal.json'),old_observation_source_seal_sha256=digest(PREVIOUS/'artifact-seal.json'),
        truth=draft['truth'],scope=draft['scope'],causal_control=draft['causal_control'],
        primary_window=dict(clock_seconds=.005,voiced_window_ms=60,source_period_spread_max_semitones=1.,
            negative_unvoiced_window_ms=40,negative_boundary_margin_ms=20),
        gate=dict(all_files=128,primary_positive_min=3,negative_min=3,correct_tolerance_semitones=1.,
            coverage_min=.9,median_error_max_semitones=1.,negative_false_accept_max=.05,
            missing_or_inadequate_denominator='fail',old_waveform_hash_all_match=True),
        exclusions='edge/dynamic/boundaryを全件数保存。45ms等の短い音素でprimary窓の適用が減ることを旧固定支持のsource診断へ明記。',
        no_old_gate_or_selection_changes=True,no_perceived_pitch_truth_claim=True,no_WORLD_or_general_Japanese_qualification=True,
        final_generator_independence_not_retested=True,saved_parameters_for_observation_only=True,
        limits=draft['limits'],cost_estimate=dict(draft['estimates'],dsp=772,fixture_DSP=4,
            retry_render=268,retry_DSP=2228,retry_storage=350000000),
        new_teacher_train_inverse_AI_download_money=0,no_new_human_response_required=True,
        no_optimization_after_first_audio=True,protected_confirmation_opened=False,quality_goal_completed=False,
        technical_retry_per_job=2,technical_retry_campaign=10,
        budget_review='22/24（91.7%）。既存実装の純粋観測監査。新しい生成経路/係数は追加しない。')
    assert reg['cost_estimate']['planned_peak_total']<reg['limits']['bytes']
    assert v['limits']['seconds']-v['seconds']-14400>=reg['limits']['seconds']
    assert all(reg['limits'][k]<=v['limits'][k]-v['counts'].get(k,0) for k in ['render','dsp','ai','teacher','train','inverse','download'])
    assert shutil.disk_usage(ROOT).free>=20000000000 and shutil.disk_usage(b.guard.root).free>=2750000000
    b.reconcile();b.start_campaign(NAME,str(HERE.relative_to(ROOT)),reg['limits'],hashlib.sha256(encode(reg)).hexdigest())
    with b.job(NAME,'setup','既存HTS励振周期の観測監査・生成前登録',reserve_bytes=400_000) as j:
        b.save(HERE/'registration.json',reg,j)
        for n,s in sources.items():b.write(HERE/n,s.encode(),j)
        for p in (LATEST/'vendor').iterdir():
            if p.is_file():b.write(HERE/'vendor'/p.name,p.read_bytes(),j)
        b.write(HERE/'HTS-BSD-NOTICE.txt',(LATEST/'HTS-BSD-NOTICE.txt').read_bytes(),j)
        b.save(HERE/'implementation-audit.json',dict(Python_AST_pass=True,source_hashes={n:hashlib.sha256(s.encode()).hexdigest() for n,s in sources.items()},
            actual_render=0,actual_AI=0,protected_confirmation_opened=False,observer_truth_only=True),j)
    with b.locked():
        s=b._load();s.setdefault('continuation_checkpoint_history',[]).append(s['continuation_checkpoint'])
        s['continuation_checkpoint']=dict(id='source-period-audit-registered-20261008-0001',active_campaign=NAME,campaign_closed=False,
            next='prepare → preflight4 → commit/push → observe128 → summarize → closeout',quality_goal_completed=False,
            protected_confirmation_opened=False,git_save_pending=True);b._write_state(s)
    b.save(ROOT/'progress-0027.json',dict(active_campaign=NAME,prior_completed='gv-ap-interaction-v1',
        quality_goal_completed=False,protected_confirmation_opened=False,next='prepare.py → controller.py preflight → commit/push → observe → summarize/closeout',budget=b.reconcile()))
    print(b.reconcile(),flush=True)
if __name__=='__main__':main()
